const NamedBitmap* icon_table() {
    return icon_table_.data();
}

size_t icon_table_size() {
    return icon_table_.size();
}

const Bitmap* icon_by_name(std::string_view name) {
    const auto it = std::find_if(
        icon_table_.begin(), icon_table_.end(),
        [name](const NamedBitmap& e) { return name == e.name; });
    return (it == icon_table_.end()) ? nullptr : it->bitmap;
}

